def scrape_twitter(url, api_key="YOUR_KEY_HERE"):
    # Create the URL
    resp = requests.get(url, headers={"User-Agent": "Mozilla/5.0"})
    try:
        resp.raise_for_status()
        soup = BeautifulSoup(resp.text, "html.parser")
        posts = soup.select_all("p", class_='content-area-post-secondary-content')

        for post in posts:
            title = post.get_text(strip=True)
            if title:
                title_text = title.strip()
                post_data = post.get_text(strip=True)

                # Titles
                for title in title_text:
                    title_text = title_text.strip()

                # Content blocks
                for block in post_data.get("content-block"):
                    content = block.get_text(strip=True)
                    caption = content.get("caption", []).append(content.strip())
                    post_data.append(caption)

                # Images
                for img in block.get("images"):
                    img_text = img.get_text(strip=True)
                    if img_text:
                        img_text = img_text.strip()
                    post_data.append(img_text)

                # Click-to-collect
                if "collapsible" in post_data:
                    for link in post_data.get("links", [False])[:5]:
                        if link:
                            post_data.append(link.get_text())
                        elif "click-to-present" in post_data.get("presentation"):
                            post_data.append(link.get_text())
                            break # Skips clicks that don't open the link

        results = []
        for post in post_data:
            results.append(post.get_text(strip=True))

        print(f"Saved {len(results)} posts")

        return results

